// Standalone fallback: resolve client_config from the Notion registry by client_id.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();
function prop(props, name){ const keys=[name,'property_'+name,'property_'+String(name).toLowerCase().replace(/ /g,'_')]; let p; for(const k of keys){ const v=props&&props[k]; if(v!==undefined&&v!==null){ p=v; break; } } if(p===undefined||p===null) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);

// Outbound identity — keep in sync with 00-orchestrator-end-to-end.json -> 'Map Client Config'.
// Both addresses must be VERIFIED 'Send mail as' aliases on the Gmail account that owns the
// credential, or Gmail rejects drafts.send.
const DEMO_FROM_ALIAS = 'demo@cifral.io';
const PROD_FROM_ALIAS = 'proposal@cifral.io';
const clientStatus = prop(match,'Client Status');

const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  status: clientStatus,
  from_alias: clientStatus === 'trial' ? DEMO_FROM_ALIAS : PROD_FROM_ALIAS,
  send_mode: String(prop(match,'send_mode') || 'send').trim().toLowerCase() === 'draft' ? 'draft' : 'send',
  service_tier: prop(match,'service_tier'),
  commercial_contact_email: prop(match,'commercial_contact_email'),
  templates: { en: prop(match,'template_id_en'), es: prop(match,'template_id_es') },
  proposals_folder_id: prop(match,'proposals_folder_id'),
  notification_chat_id: prop(match,'notification_chat_id')
};
return [{ json: { client_id: wantId, client_config, email_context: trigger.email_context || null, data: trigger.data, status: 'ok', errors: [] } }];

// Deterministic, scope-aware proposal assembly (replaces the legacy Set node).
// Fixes: B2 deterministic number; G2 template by language w/ EN fallback; G1 recipient = the
// client's own commercial contact; B1 requirements read the 'quantity' key.
// Phase 7: renders only IN-SCOPE sections. Each optional section is a single template token
// ({{SECCION_*}}); out-of-scope -> '' so the block vanishes. A visible Scope-of-Supply block
// ({{ALCANCE_SUMINISTRO}}) lets the reviewing reseller catch any wrong scope before sending.
const cfg = $json.client_config || {};
const data = $json.data || {};
const rfq = data.rfq || {};
const client = rfq.client || {};
const project = rfq.project || {};
const reqs = Array.isArray(rfq.technical_requirements) ? rfq.technical_requirements : [];
const scope = rfq.scope_of_supply || {};
const lang = (rfq.language === 'es' || rfq.language === 'en') ? rfq.language : 'en';
const content = data.content || {};
const pricing = data.pricing || null;

function hash36(str){ let h=5381; for(let i=0;i<str.length;i++){ h=((h<<5)+h+str.charCodeAt(i))>>>0; } return h.toString(36); }
const identity = [ $json.client_id, client.company, client.email, (reqs[0]&&reqs[0].item)||'' ].join('|');
const suffix = (hash36(identity) + '000000').slice(0,6).toUpperCase();
const proposal_number = `PROP-${$now.toFormat('yyyyMMdd')}-${suffix}`;

const templates = cfg.templates || {};
const template_id = templates[lang] || templates.en;
if(!template_id) throw new Error(`No Google Docs template configured for client '${$json.client_id}' (language '${lang}', no EN fallback).`);

const recipient_email = cfg.reply_to || cfg.commercial_contact_email;
if(!recipient_email) throw new Error(`No reply address for '${$json.client_id}' (sender email + commercial_contact_email both empty). Refusing to send to the extracted end customer (legacy gap G1) — this mail is DELIVERED, not parked as a draft.`);

// Outbound identity. The Gmail node's Send operation rebuilds From from the authenticated
// mailbox, so the alias only survives the create-draft -> drafts.send pair.
const from_alias = cfg.from_alias || '';
if(!from_alias) throw new Error(`No from_alias resolved for '${$json.client_id}'. Refusing to send from the raw mailbox address.`);
const send_mode = String(cfg.send_mode || 'send').trim().toLowerCase() === 'draft' ? 'draft' : 'send';

// Reply inside the reseller's original RFQ thread. Gmail threads on threadId AND a matching
// subject, so the synthetic subject is only a fallback for runs with no thread (chat trigger,
// standalone module calls). '' rather than null: the Gmail node treats it as falsy and omits
// the field, whereas null would be serialised into the API call.
const ec = $json.email_context || {};
const thread_id = ec.thread_id || '';
const email_subject = ec.reply_subject || `Proposal ${proposal_number} — ${client.company || 'Client'}`;

const requisitos_lista = reqs.map(r => '\u2022  ' + (r.item||'') + (r.quantity ? ' (x' + r.quantity + ')' : '') + (r.spec ? ': ' + r.spec : '')).join('\n');

// Scope-of-supply labels — source of truth: schemas/scope-catalog.json.
const LABELS = { materials:{en:'Materials & Equipment Supply',es:'Suministro de materiales y equipos'}, engineering:{en:'Engineering & Design',es:'Ingeniería y diseño'}, installation:{en:'Installation / Assembly',es:'Instalación / Montaje'}, commissioning:{en:'Commissioning & Start-up',es:'Puesta en marcha'}, project_management:{en:'Project Management',es:'Gestión de proyecto'}, spare_parts:{en:'Spare Parts',es:'Repuestos'}, shipping:{en:'Shipping & Logistics',es:'Transporte y logística'}, training:{en:'Training',es:'Formación'}, warranty:{en:'Warranty',es:'Garantía'} };
const order = ['materials','engineering','installation','commissioning','project_management','spare_parts','shipping','training','warranty'];
const lab = k => (LABELS[k] && LABELS[k][lang]) || k;
const incl = order.filter(k => scope[k] === true);
const excl = order.filter(k => scope[k] === false);
const inWord = lang==='es' ? 'Incluido' : 'Included';
const outWord = lang==='es' ? 'No incluido' : 'Not included';
let alcance_suministro = inWord + ':\n' + incl.map(k=>'\u2022  '+lab(k)).join('\n');
if (excl.length) alcance_suministro += '\n\n' + outWord + ':\n' + excl.map(k=>'\u2022  '+lab(k)).join('\n');

const H = { plan_implantacion:{en:'Implementation Plan',es:'Plan de implantación'}, repuestos:{en:'Spare Parts',es:'Repuestos'}, transporte:{en:'Shipping & Logistics',es:'Transporte y logística'}, formacion:{en:'Training',es:'Formación'}, garantia:{en:'Warranty',es:'Garantía'} };
// Optional sections are self-contained (uppercase heading + blank line + body) so they read as
// real chapters and vanish cleanly when out of scope. See docs/TEMPLATE-GUIDE.md.
function section(key){ const body=(content[key]||'').toString().trim(); if(!body) return ''; const h=((H[key]&&H[key][lang])||key).toUpperCase(); return h + '\n\n' + body; }

function economic(){ if(!pricing) return ''; const cur=pricing.currency||''; const title=(lang==='es'?'Oferta económica':'Economic Proposal').toUpperCase(); const subLbl=lang==='es'?'Subtotal':'Subtotal'; const totLbl=lang==='es'?'Total':'Total'; const termsLbl=lang==='es'?'Condiciones de pago':'Payment terms'; return title + '\n\n' + '\u2022  ' + subLbl + ': ' + pricing.subtotal + ' ' + cur + '\n' + '\u2022  ' + totLbl + ': ' + pricing.total + ' ' + cur + '\n' + '\u2022  ' + termsLbl + ': ' + (pricing.payment_terms||''); }

const sectionKeys = ['plan_implantacion','repuestos','transporte','formacion','garantia'];
const sections_rendered = sectionKeys.filter(k => section(k) !== '');
if (pricing) sections_rendered.push('economic');

return [{ json: {
  client_id: $json.client_id,
  language: lang,
  proposal_number,
  fecha: $now.toFormat('dd/MM/yyyy'),
  template_id,
  proposals_folder_id: cfg.proposals_folder_id,
  recipient_email,
  from_alias,
  send_mode,
  thread_id,
  email_subject,
  notification_chat_id: cfg.notification_chat_id,
  client_status: cfg.status || '',
  doc_name: `Proposal ${proposal_number} - ${client.company || 'Client'}`,
  sections_rendered,
  fields: {
    cliente_empresa: client.company || '',
    cliente_contacto: [client.contact_name, client.contact_last_name].filter(Boolean).join(' '),
    proyecto_tipo: project.type || '',
    proyecto_ubicacion: project.location || '',
    proyecto_plazo: project.desired_deadline || '',
    requisitos_lista,
    alcance_suministro,
    alcance_tecnico: content.alcance_tecnico || '',
    resumen_comercial: content.resumen_comercial || '',
    seccion_plan_implantacion: section('plan_implantacion'),
    seccion_repuestos: section('repuestos'),
    seccion_transporte: section('transporte'),
    seccion_formacion: section('formacion'),
    seccion_garantia: section('garantia'),
    seccion_economica: economic()
  },
  pricing
} }];

