// Assemble the Module 4 output envelope (schema: proposal-assembly.schema.json).
const cf = $('Compute Proposal Fields').first().json;
const copied = $('Copy Template').first().json;
let draftId = null;
try { draftId = $('Create Draft').first().json.id || $('Create Draft').first().json.message?.id || null; } catch (e) {}
// 'Send Draft' only runs on the send branch; referencing an unexecuted node throws, so the
// catch means 'send_mode was draft'. A genuine send failure fails that node and the run never
// reaches here — so 'sent:false' always means 'deliberately not sent', never 'silently lost'.
let sent_message_id = null;
try { sent_message_id = $('Send Draft').first().json.id || null; } catch (e) {}
return [{ json: {
  client_id: cf.client_id,
  status: 'ok',
  errors: [],
  data: {
    proposal_number: cf.proposal_number,
    document_id: copied.id,
    pdf_file_name: `${copied.name}.pdf`,
    draft_id: draftId,
    draft_recipient: cf.recipient_email,
    sent: cf.send_mode === 'send' && !!sent_message_id,
    sent_message_id,
    from_alias: cf.from_alias,
    thread_id: cf.thread_id || null,
    language: cf.language,
    template_id_used: cf.template_id,
    notified_chat_id: cf.notification_chat_id,
    sections_rendered: cf.sections_rendered || []
  }
} }];
